  "inlineSchema": "// Prisma schema for Shop Management System\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\n// User model with roles\nmodel User {\n  id       String  @id @default(cuid())\n  name     String\n  email    String  @unique\n  password String // bcrypt hashed\n  role     Role    @default(CUSTOMER)\n  phone    String?\n  address  String?\n\n  // Relations\n  shop   Shop?   @relation(\"CashierToShop\", fields: [shopId], references: [id])\n  shopId String?\n\n  quotations Quotation[]\n  sales      Sale[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([email])\n  @@index([role])\n}\n\nenum Role {\n  CUSTOMER\n  CASHIER\n  ADMIN\n}\n\n// Shop model for multi-shop support\nmodel Shop {\n  id       String  @id @default(cuid())\n  name     String\n  location String\n  phone    String?\n  email    String?\n\n  // Relations\n  cashiers  User[]      @relation(\"CashierToShop\")\n  products  Product[]\n  inventory Inventory[]\n  sales     Sale[]\n  expenses  Expense[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// Product model\nmodel Product {\n  id          String  @id @default(cuid())\n  name        String\n  description String?\n  sku         String  @unique\n  price       Float // Unit price\n  cost        Float? // Cost price for profit calculation\n  category    String?\n  image       String? // URL to image\n\n  // Relations\n  shop   Shop   @relation(fields: [shopId], references: [id], onDelete: Cascade)\n  shopId String\n\n  inventory      Inventory[]\n  saleItems      SaleItem[]\n  quotationItems QuotationItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([shopId, sku])\n  @@index([shopId])\n  @@index([category])\n}\n\n// Inventory tracking\nmodel Inventory {\n  id            String    @id @default(cuid())\n  quantity      Int       @default(0)\n  reorderLevel  Int       @default(5)\n  lastRestocked DateTime?\n\n  // Relations\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  productId String\n\n  shop   Shop   @relation(fields: [shopId], references: [id], onDelete: Cascade)\n  shopId String\n\n  @@unique([productId, shopId])\n  @@index([productId])\n  @@index([shopId])\n}\n\n// Sales/Invoice\nmodel Sale {\n  id            String @id @default(cuid())\n  invoiceNumber String @unique\n\n  // Relations\n  shop   Shop   @relation(fields: [shopId], references: [id])\n  shopId String\n\n  cashier   User   @relation(fields: [cashierId], references: [id])\n  cashierId String\n\n  items SaleItem[]\n\n  // Totals\n  subtotal Float @default(0)\n  tax      Float @default(0)\n  discount Float @default(0)\n  total    Float @default(0)\n\n  // Payment\n  paymentMethod PaymentMethod @default(CASH)\n  amountPaid    Float?\n  change        Float?\n  status        SaleStatus    @default(COMPLETED)\n\n  createdAt DateTime @default(now())\n\n  @@index([shopId])\n  @@index([cashierId])\n  @@index([createdAt])\n}\n\nenum PaymentMethod {\n  CASH\n  CARD\n  BANK_TRANSFER\n  CHEQUE\n}\n\nenum SaleStatus {\n  PENDING\n  COMPLETED\n  CANCELLED\n  RETURNED\n}\n\n// Sale items (line items)\nmodel SaleItem {\n  id String @id @default(cuid())\n\n  sale   Sale   @relation(fields: [saleId], references: [id], onDelete: Cascade)\n  saleId String\n\n  product   Product @relation(fields: [productId], references: [id])\n  productId String\n\n  quantity  Int\n  unitPrice Float\n  total     Float // quantity * unitPrice\n\n  @@index([saleId])\n  @@index([productId])\n}\n\n// Quotations\nmodel Quotation {\n  id              String @id @default(cuid())\n  quotationNumber String @unique\n\n  customer   User   @relation(fields: [customerId], references: [id])\n  customerId String\n\n  items QuotationItem[]\n\n  subtotal Float @default(0)\n  tax      Float @default(0)\n  total    Float @default(0)\n\n  validUntil DateTime\n  status     QuotationStatus @default(PENDING)\n  notes      String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([customerId])\n  @@index([status])\n  @@index([createdAt])\n}\n\nenum QuotationStatus {\n  PENDING\n  ACCEPTED\n  REJECTED\n  EXPIRED\n  CONVERTED_TO_SALE\n}\n\n// Quotation items\nmodel QuotationItem {\n  id String @id @default(cuid())\n\n  quotation   Quotation @relation(fields: [quotationId], references: [id], onDelete: Cascade)\n  quotationId String\n\n  product   Product @relation(fields: [productId], references: [id])\n  productId String\n\n  quantity  Int\n  unitPrice Float\n  total     Float\n\n  @@index([quotationId])\n  @@index([productId])\n}\n\n// Expenses\nmodel Expense {\n  id String @id @default(cuid())\n\n  shop   Shop?   @relation(fields: [shopId], references: [id], onDelete: SetNull)\n  shopId String?\n\n  category    ExpenseCategory\n  description String\n  amount      Float\n  receipt     String? // File URL\n\n  createdAt DateTime @default(now())\n\n  @@index([shopId])\n  @@index([category])\n  @@index([createdAt])\n}\n\nenum ExpenseCategory {\n  SUPPLIES\n  UTILITIES\n  RENT\n  SALARY\n  TRANSPORTATION\n  MAINTENANCE\n  MARKETING\n  OTHER\n}\n",
